import java.util.ArrayList;
import java.util.List;

public class Solution {
    static List<Integer> withoutDuplicates(List<Integer> values) {
        List<Integer> result = new ArrayList<>();
        for (Integer v : values) {
            if (!result.contains(v)) result.add(v);
        }
        return result;
    }

    static void removeNegatives(List<Integer> values) {
        for (int i = values.size() - 1; i >= 0; i--) {
            if (values.get(i) < 0) values.remove(i);
        }
    }

    static List<String> longWords(List<String> words, int minLength) {
        List<String> result = new ArrayList<>();
        for (String w : words) {
            if (w.length() >= minLength) result.add(w.toUpperCase());
        }
        return result;
    }

    static List<Integer> positionsOf(List<String> items, String target) {
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < items.size(); i++) {
            if (target.equals(items.get(i))) result.add(i);
        }
        return result;
    }

    static double average(List<Integer> values) {
        int count = 0;
        long sum = 0;
        for (Integer v : values) {
            if (v == null) continue;
            sum += v;
            count++;
        }
        return count == 0 ? 0.0 : (double) sum / count;
    }
}

unitTests:
test("without duplicates", () -> {
    List<Integer> input = List.of(3, 1, 3, 2, 1, 1000, 1000);
    checkEq(Solution.withoutDuplicates(input), List.of(3, 1, 2, 1000));
    checkEq(input.size(), 7);
    checkEq(Solution.withoutDuplicates(List.of()), List.of());
});

test("removing in place", () -> {
    List<Integer> values = new ArrayList<>(List.of(-1, 4, -2, -3, 7, -9));
    Solution.removeNegatives(values);
    checkEq(values, List.of(4, 7));
    List<Integer> none = new ArrayList<>(List.of(-5));
    Solution.removeNegatives(none);
    checkEq(none.size(), 0);
});

test("long words", () -> {
    checkEq(Solution.longWords(List.of("a", "java", "is", "fun", "really"), 3), List.of("JAVA", "FUN", "REALLY"));
});

test("positions", () -> {
    List<String> items = List.of("tea", "cake", "tea", "mug", "tea");
    checkEq(Solution.positionsOf(items, "tea"), List.of(0, 2, 4));
    checkEq(Solution.positionsOf(items, new String("cake")), List.of(1));
    checkEq(Solution.positionsOf(items, "pen"), List.of());
});

test("average with nulls", () -> {
    checkNear(Solution.average(List.of(1, 2, 2)), 5.0 / 3);
    checkNear(Solution.average(new ArrayList<>(java.util.Arrays.asList(4, null, 6))), 5.0);
    checkNear(Solution.average(List.of()), 0.0);
    checkNear(Solution.average(List.of(Integer.MAX_VALUE, Integer.MAX_VALUE)), Integer.MAX_VALUE);
});

